parameters.jsCode:
const allItems = $input.all();

const MISSING_VALUES = new Set(['', 'tbd', 'none', 'n/a', 'null', '-']);

const clean = (value) => {
  const text = String(value ?? '').trim();
  return MISSING_VALUES.has(text.toLowerCase()) ? '' : text;
};

const orNone = (value) => {
  const v = clean(value);
  return v ? v : 'None';
};

const stripWhitespace = (value) =>
  String(value ?? '')
    .replace(/[\u200E\u200F\u202A-\u202E\u2066-\u2069]/g, '')
    .replace(/[\r\n\t]+/g, ' ')
    .replace(/ {2,}/g, ' ')
    .trim();

const KNOWN_LABELS = [
  'Assignment ID', 'Event ID', 'Shift ID', 'Recipient Name', 'Recipient Phone',
  'Role', 'Preferred Language', 'Location Name', 'Address', 'Maps Link', 'Date',
  'Arrival Time', 'All Shift Times', 'Manager Name', 'Manager Phone', 'Client Name',
  'Client Phone', 'Number of Workers', 'Workers Per Shift', 'Staff List',
  'Dress Code', 'Notes', 'Cash Plan', 'Money Holder', 'Calendar Link', 'Closeout Sheet'
];

const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const labelAlternation = KNOWN_LABELS.map(escapeRegex).join('|');

const field = (text, label) => {
  const re = new RegExp(`(?:^|\\n)${escapeRegex(label)}:[ \\t]*([^\\r\\n]*)`, 'i');
  const m = text.match(re);
  return m ? clean(m[1]) : '';
};

const section = (text, label) => {
  const re = new RegExp(
    `${escapeRegex(label)}:[ \\t]*\\n([\\s\\S]*?)(?=\\n[ \\t]*(?:${labelAlternation}):|\\n[ \\t]*\\n|$)`,
    'i'
  );
  const m = text.match(re);
  return m ? m[1].trim() : '';
};

const fieldOrNextLine = (text, label) => {
  const sameLine = field(text, label);
  if (sameLine) return sameLine;
  const re = new RegExp(`${escapeRegex(label)}:\\s*\\n([^\\r\\n]*)`, 'i');
  const m = text.match(re);
  return m ? clean(m[1]) : '';
};

const parsedRows = allItems.map((item) => {
  const row = item.json;
  const text = String(row['Event WhatsApp Summary'] || '');

  return {
    row,
    text,
    eventId: clean(row['Event ID']) || field(text, 'Event ID'),
    role: clean(row['Role']) || field(text, 'Role'),
    recipientName: field(text, 'Recipient Name') || clean(row['Worker Name']),
    recipientPhone: field(text, 'Recipient Phone') || clean(row['Phone']),
    isEventLead: row['Event Lead?'] === true || String(row['Event Lead?']).toLowerCase() === 'true'
  };
});

const eventFacts = {};

for (const eventId of new Set(parsedRows.map(r => r.eventId).filter(Boolean))) {
  const rowsForEvent = parsedRows.filter(r => r.eventId === eventId);

  const manager = rowsForEvent.find(r => r.role.trim().toLowerCase() === 'manager');
  const eventLead = !manager && rowsForEvent.find(r => r.isEventLead);
  const source = manager || eventLead || null;

  const workerCount = rowsForEvent.filter(
    r => r.role.trim().toLowerCase() !== 'manager'
  ).length;

  eventFacts[eventId] = {
    managerName: source ? source.recipientName : '',
    managerPhone: source ? source.recipientPhone : '',
    workerCount
  };
}

return parsedRows.map(({ row, text, eventId, role }) => {

  const recipientName = field(text, 'Recipient Name') || clean(row['Worker Name']);
  const recipientPhone = field(text, 'Recipient Phone') || clean(row['Phone']);

  const locationName = field(text, 'Location Name');
  const address = field(text, 'Address');
  const mapsLink = fieldOrNextLine(text, 'Maps Link');

  const date = field(text, 'Date');
  const arrivalTime = field(text, 'Arrival Time');

  const clientName = field(text, 'Client Name');
  const clientPhone = field(text, 'Client Phone');

  const calendarLink = fieldOrNextLine(text, 'Calendar Link');
  const closeoutSheet = fieldOrNextLine(text, 'Closeout Sheet');

  const facts = eventFacts[eventId] || { managerName: '', managerPhone: '', workerCount: 0 };
  const managerName = facts.managerName;
  const managerPhone = facts.managerPhone;
  const numberOfWorkers = String(facts.workerCount);

  let notes = stripWhitespace(section(text, 'Notes'));
  if (/cash plan|money holder/i.test(notes)) {
    notes = '';
  }

  const rawDressCode = section(text, 'Dress Code');
  let dressCode = '';
  if (rawDressCode) {
    const parts = rawDressCode
      .split('\n')
      .map(line => line.replace(/[•~]/g, '').trim())
      .filter(Boolean);
    dressCode = parts.join('; ');
  }

  const mapsBase = 'https://www.google.com/maps/search/?api=1&query=';
  const locationButtonPayload = mapsLink.startsWith(mapsBase)
    ? mapsLink.slice(mapsBase.length)
    : (address ? encodeURIComponent(address) : (locationName ? encodeURIComponent(locationName) : ''));

  const calendarBase = 'https://calendar.google.com/calendar/render?';
  const calendarButtonPayload = calendarLink.startsWith(calendarBase)
    ? calendarLink.slice(calendarBase.length)
    : '';

  const closeoutBase = 'https://docs.google.com/spreadsheets/d/';
  const closeoutButtonPayload = closeoutSheet.startsWith(closeoutBase)
    ? closeoutSheet.slice(closeoutBase.length)
    : '';

  const isManager = role.trim().toLowerCase() === 'manager';

  const problems = [];

  if (!recipientPhone) problems.push('Recipient Phone is missing (cannot send WhatsApp)');
  if (!mapsLink) problems.push('Maps Link is missing');
  if (!arrivalTime) problems.push('Arrival Time is missing');

  if (!isManager && !calendarLink) problems.push('Calendar Link is missing (required for worker template)');
  if (isManager && !closeoutSheet) problems.push('Closeout Sheet is missing (required for manager template)');

  const status = problems.length === 0 ? 'OK' : 'ERROR';

  const escalationMessage = status === 'ERROR'
    ? `⚠️ WHATSAPP ASSIGNMENT NEEDS REVIEW\n\nThe normal WhatsApp message was NOT sent.\n\nRecipient Name: ${orNone(recipientName)}\nRecipient Phone: ${orNone(recipientPhone)}\nRole: ${orNone(role)}\nDate: ${orNone(date)}\nArrival Time: ${orNone(arrivalTime)}\nLocation Name: ${orNone(locationName)}\nAddress: ${orNone(address)}\nMaps Link: ${orNone(mapsLink)}\nManager Name: ${orNone(managerName)}\nManager Phone: ${orNone(managerPhone)}\nClient Name: ${orNone(clientName)}\nClient Phone: ${orNone(clientPhone)}\nCalendar Link: ${orNone(calendarLink)}\nCloseout Sheet: ${orNone(closeoutSheet)}\n\nMissing critical information:\n${problems.map(p => `• ${p}`).join('\n')}\n\n--- Original Event WhatsApp Summary ---\n${text}\n\nPlease review the assignment in Workforce Demo DB and contact the worker/manager directly if necessary.`
    : '';

  return {
    json: {
      Status: status,
      'Sheet Status': clean(row['Status']),
      'Template Type': isManager ? 'MANAGER' : 'WORKER',
      'Error Message': problems.join(' | '),
      'Escalation Message': escalationMessage,

      'Assignment ID': clean(row['Assignment ID']),
      'Worker ID': clean(row['Worker ID']),

      'Recipient Name': orNone(recipientName),
      'Recipient Phone': recipientPhone,
      Role: role,

      'Location Name': orNone(locationName),
      Address: orNone(address),
      'Maps Link': mapsLink,
      'Event Date': orNone(date),
      'Arrival Time': arrivalTime,

      'Manager Name': orNone(managerName),
      'Manager Phone': orNone(managerPhone),

      'Client Name': orNone(clientName),
      'Client Phone': orNone(clientPhone),
      'Number of Workers': numberOfWorkers,

      'Dress Code': dressCode ? dressCode : 'None',
      Notes: notes ? notes : 'None',

      'Calendar Link': calendarLink,
      'Closeout Sheet': closeoutSheet,

      'Location Button Payload': locationButtonPayload,
      'Calendar Button Payload': calendarButtonPayload,
      'Closeout Button Payload': closeoutButtonPayload
    }
  };
});

