={{ (() => {
  const clean = v => String(v ?? '').replace(/[\r\n\t]+/g, ' ').replace(/ {2,}/g, ' ').trim();
  return JSON.stringify({
    messaging_product: "whatsapp",
    to: $json["Recipient Phone"],
    type: "template",
    template: {
      name: "manager_template",
      language: { code: "en" },
      components: [
        { type: "body", parameters: [
          { type: "text", parameter_name: "client_name", text: clean($json["Client Name"]) },
          { type: "text", parameter_name: "client_phone", text: clean($json["Client Phone"]) },
          { type: "text", parameter_name: "location", text: clean($json["Location Name"]) },
          { type: "text", parameter_name: "arrival_time", text: clean($json["Arrival Time"]) },
          { type: "text", parameter_name: "number_of_workers", text: clean($json["Number of Workers"]) },
          { type: "text", parameter_name: "notes", text: clean($json["Notes"]) }
        ]},
        { type: "button", sub_type: "quick_reply", index: "0", parameters: [{ type: "payload", payload: "Confirm" }] },
        { type: "button", sub_type: "quick_reply", index: "1", parameters: [{ type: "payload", payload: "Decline" }] },
        { type: "button", sub_type: "url", index: "2", parameters: [{ type: "text", text: clean($json["Location Button Payload"]) }] },
        { type: "button", sub_type: "url", index: "3", parameters: [{ type: "text", text: clean($json["Closeout Button Payload"]) }] }
      ]
    }
  });
})() }}

